// Hora do disparo → janela de entrega. As janelas espelham as opções que o
// app oferece no onboarding (Amanhecer/Manhã/Meio-dia/Noite).
const hora = new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo', hour: '2-digit', hour12: false });
const h = parseInt(hora, 10);
const janela = h < 8 ? 'dawn' : h < 11 ? 'morning' : h < 15 ? 'noon' : 'evening';
return [{ json: { window: janela } }];
